"""Compare bounded memory policies on a causal stream of recurring, changing rules."""
import json
import math
import random
import sys
from collections import Counter, OrderedDict, deque
from dataclasses import dataclass
from pathlib import Path

from rich.console import Console


CAPACITY = 48
SEEDS = (2131, 2137, 2141, 2143, 2153, 2161, 2179, 2203, 2207, 2213, 2221, 2237)
STEPS = 2048
VALUES = 5
ARMS = ("latest", "trusted_latest", "recent_weighted", "per_context_weighted", "consolidated")


@dataclass(frozen=True)
class Record:
    key: int
    value: int
    source: int
    reliability: float
    time: int


def score(records, time, half_life=42):
    totals = Counter()
    for record in records:
        trust = math.log(record.reliability / ((1 - record.reliability) / (VALUES - 1)))
        totals[record.value] += trust * 2 ** (-(time - record.time) / half_life)
    if not totals:
        return None
    return max(totals, key=lambda value: (totals[value], -value))


class Latest:
    def __init__(self, trusted=False):
        self.records = OrderedDict()
        self.trusted = trusted

    def predict(self, key, time):
        observed = self.records.get(key)
        return observed.value if observed is not None else None

    def write(self, observed):
        old = self.records.get(observed.key)
        if self.trusted and old is not None and observed.reliability < old.reliability and observed.time - old.time < 42:
            return
        self.records[observed.key] = observed
        self.records.move_to_end(observed.key)
        if len(self.records) > CAPACITY:
            self.records.popitem(last=False)

    def slots(self):
        return len(self.records)


class RecentWeighted:
    def __init__(self, grouped=False):
        self.records = deque(maxlen=CAPACITY)
        self.grouped = grouped

    def predict(self, key, time):
        return score([row for row in self.records if row.key == key], time)

    def write(self, observed):
        if self.grouped:
            matches = [index for index, row in enumerate(self.records) if row.key == observed.key]
            if len(matches) >= 3:
                del self.records[matches[0]]
            elif len(self.records) == CAPACITY:
                counts = Counter(row.key for row in self.records)
                if max(counts.values()) > 1:
                    index = next(i for i, row in enumerate(self.records) if counts[row.key] == max(counts.values()))
                    del self.records[index]
        self.records.append(observed)

    def slots(self):
        return len(self.records)


class Consolidated:
    """Promote only recent corroboration from more than one source."""

    def __init__(self):
        self.recent = deque(maxlen=CAPACITY // 2)
        self.durable = OrderedDict()

    def predict(self, key, time):
        rows = [row for row in self.recent if row.key == key]
        if key in self.durable:
            return self.durable[key].value
        return score(rows, time)

    def write(self, observed):
        self.recent.append(observed)
        latest_per_source = {}
        for row in self.recent:
            if row.key == observed.key and observed.time - row.time <= 18:
                latest_per_source[row.source] = row
        records = list(latest_per_source.values())
        preferred = score(records, observed.time)
        supporting = [row for row in records if row.value == preferred]
        if len(supporting) >= 2 and any(row.reliability >= 0.8 for row in supporting):
            self.durable[observed.key] = max(supporting, key=lambda row: row.time)
            self.durable.move_to_end(observed.key)
            if len(self.durable) > CAPACITY // 2:
                self.durable.popitem(last=False)

    def slots(self):
        return len(self.recent) + len(self.durable)


def witnesses():
    model = Consolidated()
    older = Record(3, 1, 0, 0.94, 0)
    corroborated = Record(3, 1, 1, 0.83, 1)
    weak_conflict = Record(3, 4, 3, 0.53, 2)
    fresh_authority = Record(3, 2, 0, 0.94, 3)
    new_confirmation = Record(3, 2, 1, 0.83, 4)
    for record in (older, corroborated, weak_conflict):
        model.write(record)
    assert model.predict(3, 3) == 1 and model.slots() == 4
    model.write(fresh_authority)
    latest = Latest()
    for record in (older, corroborated, weak_conflict, fresh_authority):
        latest.write(record)
    assert model.predict(3, 4) == 1 and latest.predict(3, 4) == 2
    model.write(new_confirmation)
    assert model.predict(3, 5) == 2
    return {"corroboration_preserves_correct_old_binding": True, "one_authoritative_revision_can_temporarily_lose": True,
            "independent_corroboration_updates_durable_value": True}


def stream(seed):
    rng = random.Random(seed)
    gold = [rng.randrange(VALUES) for _ in range(36)]
    past = set()
    revised_until = {}
    prior = {}
    last_domain = None
    domain = 0
    for index in range(STEPS):
        if index % 32 == 0:
            last_domain = domain if index else None
            domain = (index // 32 + rng.randrange(3)) % 6
        key = 6 * domain + rng.randrange(6)
        if key in past and rng.random() < 0.045:
            prior[key] = gold[key]
            gold[key] = (gold[key] + 1 + rng.randrange(VALUES - 1)) % VALUES
            revised_until[key] = index + 8
        phase = "routine"
        if key not in past:
            phase = "unseen"
        elif index <= revised_until.get(key, -1):
            phase = "revision"
        elif last_domain is not None and domain != last_domain and index % 32 < 8:
            phase = "return"
        source = rng.randrange(4)
        reliability = (0.94, 0.83, 0.67, 0.53)[source]
        value = gold[key]
        reported = value if rng.random() < reliability else (value + 1 + rng.randrange(VALUES - 1)) % VALUES
        yield phase, value, prior.get(key) if phase == "revision" else None, Record(key, reported, source, reliability, index)
        past.add(key)


def run_seed(seed):
    policies = dict(zip(ARMS, (Latest(), Latest(True), RecentWeighted(), RecentWeighted(True), Consolidated()), strict=True))
    outcomes = {arm: {} for arm in ARMS}
    high_water = {arm: 0 for arm in ARMS}
    for phase, gold, old_gold, observed in stream(seed):
        for name, policy in policies.items():
            prediction = policy.predict(observed.key, observed.time)
            flags = outcomes[name].setdefault(phase, [])
            if prediction is None:
                flags.append(0)
            elif prediction == gold:
                flags.append(1)
            elif prediction == old_gold:
                flags.append(3)
            else:
                flags.append(2)
            policy.write(observed)
            high_water[name] = max(high_water[name], policy.slots())
            assert high_water[name] <= CAPACITY
    scores = {name: {phase: {"queries": len(rows), "correct": rows.count(1), "abstained": rows.count(0),
                             "wrong": rows.count(2) + rows.count(3), "stale": rows.count(3),
                             "outcomes": "".join(map(str, rows))}
                     for phase, rows in phases.items()} for name, phases in outcomes.items()}
    return {"scores": scores, "high_water_records": high_water}


def decision(rows):
    totals = {arm: Counter() for arm in ARMS}
    per_class = {arm: {} for arm in ARMS}
    for row in rows.values():
        for arm, scores in row["scores"].items():
            for phase, fields in scores.items():
                per_class[arm].setdefault(phase, Counter()).update({k: v for k, v in fields.items() if k != "outcomes"})
                totals[arm].update({k: v for k, v in fields.items() if k != "outcomes"})
    best = max(ARMS[:-1], key=lambda arm: totals[arm]["correct"])
    gain = (totals["consolidated"]["correct"] - totals[best]["correct"]) / totals[best]["queries"]
    guard = {phase: (per_class["consolidated"][phase]["correct"] - per_class[best][phase]["correct"]) / per_class[best][phase]["queries"]
             for phase in ("return", "revision")}
    return {"totals": totals, "per_class": per_class, "strongest_control": best, "accuracy_gain": gain,
            "guard_gains": guard, "advance": gain >= 0.05 and min(guard.values()) >= -0.02}


if __name__ == "__main__":
    proof = witnesses()
    evidence = {str(seed): run_seed(seed) for seed in SEEDS}
    verdict = decision(evidence)
    output = {"design": {"seeds": SEEDS, "query_before_observation": True, "queries_per_seed": STEPS,
                        "logical_records_per_policy": CAPACITY, "advance_min_gain": 0.05,
                        "advance_max_guard_loss": 0.02,
                        "outcome_codes": {"0": "abstain", "1": "correct", "2": "wrong", "3": "stale"}},
              "witnesses": proof, "rows": evidence, "decision": verdict}
    Console().print_json(data=verdict)
    with Path(sys.argv[1]).open("x", encoding="utf-8") as stream_file:
        json.dump(output, stream_file, sort_keys=True, allow_nan=False)
